#!/bin/sh
set -eu

# Injects runtime configuration into config.js before nginx starts serving.
# This allows Helm values.yaml to configure the frontend dynamically without rebuilding images.
TARGET="/usr/share/nginx/html/config.js"
API_URL="${API_BASE_URL:-}"

cat <<EOF > "$TARGET"
// Auto-generated by container entrypoint at $(date -u +"%Y-%m-%dT%H:%M:%SZ")
window.__APP_CONFIG__ = {
  apiBaseUrl: "${API_URL}"
};
EOF

echo "runtime-config: generated $TARGET with apiBaseUrl='${API_URL}'"
